INSERT INTO MSVMSVCDEF
   (SERVICE_NAME, MODULE_NAME, SERVICE_MODE, SERVICE_CATEGORY, SERVICE_DESC_1, SERVICE_DESC_2, SERVICE_DESC_3, SEC_CHK_FLAG, SHARED_LIB_NAME, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME)
 VALUES
   ('WIP_Adapt_Lot', 'WIP', 'RR', 'T', 'Calibrating property information of the lot such as Material, Flow, Operation are called Adapt. The property information available for calibrating in Adapt include general information such as Material, Flow, Operation, quantity, Lot Type, priority and Rework related setup information such as Rework Return Flow, Return Operation and Resource related information such as Reserve Resource ID and other information.
Because Adapt cannot be executed for the lot on hold, you should execute Release first and then adopt the lot on hold.
In addition, when a factory is changed because the lot has been shipped, it is impossible to adapt the lot in another factory from the current factory. In other words, only the lots located in the current factory can be adapted.', 'Lot의 Material, Flow, Operation, 수량 등 Lot의 각종 속성 정보를 보정하는 것을 Adapt 라 한다.
Adapt에서 보정 가능한 속성 정보는 Material, Flow, Operation, 수량, Lot Type, Priority와 같은 Lot의 General Information과 Rework Return Flow, Return Operation과 같은 Rework 관련 설정 정보, Reserve Resource ID와 같은 Resource 관련 정보 및 기타 정보들이 해당된다.
Hold된 Lot에 대해서는 Adapt 수행이 불가능하므로 Hold된 Lot을 Adapt 처리할 경우 먼저 Release를 수행한 후 Adapt를 하여야 한다.
또한, 이미 Shipping 처리되어 Factory가 달라진 경우, 현재의 Factory에서 다른 Factory에 있는 Lot을 Adapt 처리하는 것은 불가능하며 반드시 현재의 Factory에 존재하는 Lot만 Adapt 처리할 수 있다.', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
