INSERT INTO MSVMSVCDEF
   (SERVICE_NAME, MODULE_NAME, SERVICE_MODE, SERVICE_CATEGORY, SERVICE_DESC_1, SERVICE_DESC_2, SERVICE_DESC_3, SEC_CHK_FLAG, SHARED_LIB_NAME, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME)
 VALUES
   ('WIP_Reserve_Lot', 'WIP', 'RR', 'T', 'This is for reserving Lot in a specified resource. Lot that is reserved through this transaction can be only processed by the reserved information, when transacting<Start Lot>. If it is "Resource Base", Lot list is indicated on the screen in the priority of being able to be processed when selecting resource. Multiple numbers of Lots can be selected and transacted. If it is "Lot Base", resource is to be selected after entering Lot.
If reserving in detail on sub resource and port of resource, sub resource and port is to be entered.', 'Lot을 특정 장비에서 작업하도록 예약한다. 이 Transaction을 통해 예약된 Lot은<Start Lot> Transaction 시에 뮈드시 예약된 정보에 의해서만 진행할 수 있다. "Resource Base" 인 경우 장비선택 시 진행할 수 있는 우선순위 Lot 리스트를 화면에 표시한다. 이 리스트에서 여러 개의 Lot 을 선택할 수 있고 Transaction 발뼁시킬 수 있다. "Lot Base" 인 경우 Lot 입력후 장비를 선택한다.
장비에 대한 서브장비, 포트에 대해서 자세히 예약을 설정할 경우 서브장비와 포트를 입력한다.', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
INSERT INTO MSVMSVCDEF
   (SERVICE_NAME, MODULE_NAME, SERVICE_MODE, SERVICE_CATEGORY, SERVICE_DESC_1, SERVICE_DESC_2, SERVICE_DESC_3, SEC_CHK_FLAG, SHARED_LIB_NAME, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME)
 VALUES
   ('WIP_Reserve_Sublot', 'WIP', 'RR', 'T', 'This is for reserving SubLot in a specified resource. SubLot that is reserved through this transaction can be only processed by the reserved information, when transacting<Start SubLot>. If reserving in detail on sub resource and port of resource, sub resource and port is to be entered.', 'SubLot을 특정 장비에서 작업하도록 예약한다. 이 Transaction을 통해 예약된 SubLot은<Start SubLot> Transaction 시에 뮈드시 예약된 정보에 의해서만 진행할 수 있다. 장비에 대한 서브장비, 포트에 대해서 자세히 예약을 설정할 경우 서브장비와 포트를 입력한다.', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
